// Sprite caché, injecté une seule fois juste après <body> : chaque icône utilisée dans les
// templates référence ensuite <use href="#icon-NOM">, sans jamais recharger de tracé ni
// dépendre d'un fichier externe.
function spa_render_icon_sprite() {
  echo '<svg aria-hidden="true" style="position:absolute;width:0;height:0;overflow:hidden" xmlns="http://www.w3.org/2000/svg">';
  foreach (spa_icon_glyphs() as $name => $path) {
    echo '<symbol id="icon-' . esc_attr($name) . '" viewBox="0 0 960 960"><path d="' . esc_attr($path) . '"/></symbol>';
  }
  echo '</svg>';
}
add_action('wp_body_open', 'spa_render_icon_sprite', 1);

// Balisage d'un pictogramme, à utiliser à la place de l'ancien <span class="material-symbols-outlined">.
// Conserve la même classe (donc toutes les règles CSS existantes qui la ciblent pour la couleur,
// la taille via font-size, etc. continuent de s'appliquer sans modification) et le même
// aria-hidden, puisque ces icônes restent purement décoratives.
function spa_icon($name, $extra_class = '') {
  $class = trim('material-symbols-outlined ' . $extra_class);
  return '<svg class="' . esc_attr($class) . '" aria-hidden="true" focusable="false"><use href="#icon-' . esc_attr($name) . '"></use></svg>';
}
